assert(aiBody.includes('分域能力清单') || aiBody.includes('AI 能力设计'), 'AI 总工作台缺少能力清单标题')
assert(!aiBody.includes('石油液体') || !page.locator('.business-page-header .ant-segmented').count(), 'AI 总页仍暴露石油/天然气切换')
const hasEnergyToggle = await page.locator('.business-page-header .ant-segmented').count()
assert(hasEnergyToggle === 0, 'AI 总页页头仍有 Segmented（油气切换）')
assert(await page.locator('.business-sider').getByText('AI 辅助').count() >= 1, '左侧导航缺少独立「AI 辅助」页签')

// 产量规划子菜单顺序：基础数据 → 任务编排 → 规划工作表
const planningLabels = await page.locator('.business-sider .ant-menu-submenu').filter({ hasText: '产量规划' }).locator('.ant-menu-item').allTextContents()
const joined = planningLabels.map((t) => t.trim()).filter(Boolean).join('|')
assert(joined.includes('基础数据') && joined.indexOf('任务编排') < joined.indexOf('规划工作表'), `产量规划子菜单顺序不对: ${joined}`)
await page.screenshot({ path: join(outDir, 'planning-ai-hub.png'), fullPage: false })

// 顶栏可开助手侧栏
await page.getByRole('button', { name: /智能助手/ }).click()
await page.waitForTimeout(400)
assert(await page.locator('.ant-drawer.assistant-drawer, .assistant-drawer').count() > 0, '顶栏智能助手未打开侧栏')

