/**
 * Full UI pass: visit all primary routes, catch duplicate CTAs / console errors / broken nav.
 * Usage: DEMO_BASE=http://127.0.0.1:4173 node scripts/ui-full-pass-check.mjs
 */
import { chromium } from 'playwright'
import { mkdirSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const BASE = process.env.DEMO_BASE || 'http://127.0.0.1:4173'
const outDir = join(dirname(fileURLToPath(import.meta.url)), '../docs/screenshots/ui-full-pass-2026-07-27')
mkdirSync(outDir, { recursive: true })

const failures = []
function assert(cond, msg) {
  if (!cond) failures.push(msg)
}

const routes = [
  { path: '/dashboard', name: 'dashboard' },
  { path: '/reserve/history-cleaning', name: 'reserve-base' },
  { path: '/reserve/collection', name: 'reserve-workbook' },
  { path: '/reserve/analysis', name: 'reserve-analysis' },
  { path: '/reserve/version', name: 'reserve-version' },
  { path: '/planning/collection', name: 'planning-base' },
  { path: '/planning/task', name: 'planning-task' },
  { path: '/planning/workbook', name: 'planning-workbook' },
  { path: '/planning/ai', name: 'planning-ai' },
  { path: '/admin', name: 'admin' },
]

const browser = await chromium.launch({ headless: true, channel: 'chrome' })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
const pageErrors = []
page.on('pageerror', (err) => pageErrors.push(String(err)))
page.on('console', (msg) => {
  if (msg.type() === 'error') pageErrors.push(`console: ${msg.text()}`)
})

await page.goto(BASE + '/', { waitUntil: 'networkidle' })
await page.getByText('项目演示环境').first().click()
await page.waitForURL('**/dashboard**')

for (const route of routes) {
  await page.goto(BASE + route.path, { waitUntil: 'networkidle' })
  await page.waitForTimeout(500)
  const body = await page.locator('.business-page, .app-shell').first().innerText().catch(() => '')
  assert(body.length > 40, `${route.name}: 页面正文过短或未渲染`)
  assert(!body.includes('Demo 权限模拟'), `${route.name}: 顶栏仍有 Demo 权限模拟`)
  await page.screenshot({ path: join(outDir, `${route.name}.png`), fullPage: false })
}

// 储量基础数据：页头不得再有与正文卡片重复的导入按钮
await page.goto(BASE + '/reserve/history-cleaning', { waitUntil: 'networkidle' })
await page.waitForTimeout(400)
const reserveHeader = await page.locator('.business-page-header').innerText()
assert(!reserveHeader.includes('内部数据导入'), '储量基础数据页头仍有「内部数据导入」（与正文卡片重复）')
assert(!reserveHeader.includes('上市数据导入'), '储量基础数据页头仍有「上市数据导入」（与正文卡片重复）')
assert(await page.locator('.import-entry-card').count() >= 2, '储量基础数据缺少正文模板导入卡片')

// 产量基础数据：页头不得重复「下载模板/导入」「字段字典维护」
await page.goto(BASE + '/planning/collection', { waitUntil: 'networkidle' })
await page.waitForTimeout(400)
const planningHeader = await page.locator('.business-page-header').innerText()
assert(!planningHeader.includes('下载模板'), '产量基础数据页头仍有下载模板/导入（与接入卡片重复）')
assert(!planningHeader.includes('字段字典维护'), '产量基础数据页头仍有字段字典维护（与正文维护入口重复）')
assert(await page.locator('.ds-card').filter({ hasText: 'Excel' }).count() >= 1, '产量基础数据缺少 Excel 导入卡片')

// 任务编排：状态标签不在页头与正文各贴一份
await page.goto(BASE + '/planning/task', { waitUntil: 'networkidle' })
await page.waitForTimeout(400)
const taskHeaderTags = await page.locator('.business-page-header .ant-tag').count()
assert(taskHeaderTags === 0, `任务编排页头仍有状态 Tag（与正文重复），count=${taskHeaderTags}`)

// 规划工作表：检查器无 AI Tab；有 Sheet 侧栏
await page.goto(BASE + '/planning/workbook', { waitUntil: 'networkidle' })
await page.waitForTimeout(600)
assert(await page.locator('.sheet-button').count() >= 2, '规划工作表缺少 Sheet 侧栏按钮')
assert(await page.locator('.inspector-panel .segmented-tabs').getByText('AI', { exact: true }).count() === 0, '规划检查器仍有 AI Tab')

// AI 总页：无油气 Segmented
await page.goto(BASE + '/planning/ai', { waitUntil: 'networkidle' })
await page.waitForTimeout(400)
assert(await page.locator('.business-page-header .ant-segmented').count() === 0, 'AI 总页仍有油气切换')

// 导航顺序
const planningLabels = await page.locator('.business-sider .ant-menu-submenu').filter({ hasText: '产量规划' }).locator('.ant-menu-item').allTextContents()
const joined = planningLabels.map((t) => t.trim()).filter(Boolean).join('|')
assert(joined.indexOf('任务编排') >= 0 && joined.indexOf('任务编排') < joined.indexOf('规划工作表'), `产量规划子菜单顺序不对: ${joined}`)

const seriousErrors = pageErrors.filter((e) => !/ResizeObserver|favicon|Download the React/i.test(e))
assert(seriousErrors.length === 0, `页面运行时错误: ${seriousErrors.slice(0, 5).join(' | ')}`)

await browser.close()

if (failures.length) {
  console.error('UI full-pass FAILED:')
  for (const f of failures) console.error(' -', f)
  process.exit(1)
}
console.log('UI full-pass PASS')
console.log('Screenshots:', outDir)
console.log('Routes checked:', routes.map((r) => r.path).join(', '))

